export type SortField = 'title' | 'recently-added';
export type SortOrder = 'ascending' | 'descending';

export interface MenuItemDef {
	label: string;
	afterLabel?: string;
	hideIconOnTransition?: boolean;
	closeAfter?: number;
	icon?: string;
	disabled?: boolean;
	action?: () => void;
	menuOpenOnClick?: boolean;
	children?: MenuGroupDef[];
	styles?: Record<string, string>;
}

export interface MenuGroupDef {
	title?: string;
	items: MenuItemDef[];
}

export function canWebShare(url?: string): boolean {
	if (typeof window === 'undefined' || !window.navigator) return false;
	try {
		if (typeof navigator.canShare === 'function') {
			return navigator.canShare({ url: url ?? window.location.href });
		}
	} catch { /* canShare threw */ }
	return typeof navigator.share === 'function';
}

export function createShareCopyMenu(urlFn: () => string, extraItems?: MenuItemDef[]): MenuGroupDef[] {
	const canShare = canWebShare();
	const items: MenuItemDef[] = [];
	if (extraItems) {
		items.push(...extraItems);
	}
	if (canShare) {
		items.push({ label: '分享', icon: ICONS.SHARE, menuOpenOnClick: true, styles: { '--ctxmenu-submenu-min-width': '185px' }, action: () => {
			try { navigator.share({ url: urlFn() }); } catch { /* user cancelled or sharing failed */ }
		} });
	}
	items.push({ label: '拷贝链接', icon: ICONS.LINK, afterLabel: '已拷贝链接', hideIconOnTransition: true, closeAfter: 1000, action: () => {
		const url = urlFn();
		if (navigator.clipboard?.writeText) {
			navigator.clipboard.writeText(url).catch(() => {
				const ta = document.createElement('textarea');
				ta.value = url;
				ta.style.cssText = 'position:fixed;opacity:0';
				document.body.appendChild(ta);
				ta.select();
				document.execCommand('copy');
				document.body.removeChild(ta);
			});
		} else {
			const ta = document.createElement('textarea');
			ta.value = url;
			ta.style.cssText = 'position:fixed;opacity:0';
			document.body.appendChild(ta);
			ta.select();
			document.execCommand('copy');
			document.body.removeChild(ta);
		}
	} });
	return [{ items }];
}

